use glam::{DVec3,DMat4};use ingetrazo_core::{scene::{Scene,SelectionItem},math::Ray,groups::Group};use ingetrazo_tools::{base::{Tool,ToolContext},move_tool::MoveTool};use serde_json::{json,Value};
fn copy(s:&mut Scene,d:DVec3){let mut t=MoveTool::new();let mut c=ToolContext::new(DVec3::ZERO,Ray::new(DVec3::Z*10.,-DVec3::Z));c.ctrl_held=true;t.on_click(s,&c);t.on_click(s,&ToolContext::new(d,c.ray));assert!(t.error_message().is_none());}
fn points(g:&Group,parent:DMat4,out:&mut Vec<[f64;3]>){let x=parent*g.transform;for e in &g.mesh.edges{out.push(x.transform_point3(g.mesh.vertices[e.v0].position).to_array());out.push(x.transform_point3(g.mesh.vertices[e.v1].position).to_array());}for c in &g.children{points(c,x,out);}}
fn main(){let mut rows:Vec<Value>=vec![];let mut s=Scene::new();let a=s.mesh.add_vertex(DVec3::ZERO);let b=s.mesh.add_vertex(DVec3::X);let c=s.mesh.add_vertex(DVec3::new(1.,1.,0.));let e=s.mesh.add_edge(a,b).unwrap();let f=s.mesh.add_edge(b,c).unwrap();for id in [e,f]{s.mesh.edges[id].soft=true;s.mesh.edges[id].curve_id=Some(91);}s.select(SelectionItem::Edge(e));s.select(SelectionItem::Edge(f));copy(&mut s,DVec3::X*5.);let m=&s.mesh;rows.push(json!({"name":"selected-curve","edges":m.edges.len(),"source_curve":m.edges[0].curve_id,"copied_curve":m.edges[3].curve_id,"copied_link":m.edges[2].curve_id==m.edges[3].curve_id,"fresh_curve":m.edges[3].curve_id!=m.edges[0].curve_id,"copied_soft":[m.edges[2].soft,m.edges[3].soft],"copied_attrs":[m.edges[2].attrs,m.edges[3].attrs]}));
for linked in [false,true]{let mut s=Scene::new();let mut g=Group::new("parent");let a=g.mesh.add_vertex(DVec3::ZERO);let b=g.mesh.add_vertex(DVec3::X);g.mesh.add_edge(a,b);g.transform=DMat4::from_translation(DVec3::new(2.,3.,0.));g.native_document=json!({"material":{"color":[1,0,0]},"ext":{"vendor":{"path":"do-not-remap"}}});let mut child=Group::new("child");let a=child.mesh.add_vertex(DVec3::ZERO);let b=child.mesh.add_vertex(DVec3::Y);child.mesh.add_edge(a,b);let childid=child.id;g.children.push(child);let id=g.id;s.groups.push(g);if linked{s.make_component(id).unwrap();}s.select(SelectionItem::Group(0));copy(&mut s,DVec3::X*5.);let c=&s.groups[1];let mut pts=vec![];points(c,DMat4::IDENTITY,&mut pts);rows.push(json!({"name":if linked{"component"}else{"ordinary"},"world_points":pts,"material":c.native_document["material"],"ext":c.native_document["ext"],"fresh_root":c.id!=id,"fresh_child":c.children[0].id!=childid,"component":c.component_definition.is_some(),"shared_component_mesh":if linked{json!(c.component_definition==s.groups[0].component_definition)}else{Value::Null}}));}
let mut t=MoveTool::new();let mut states=vec![];for _ in 0..3{t.note_control_state(true);let state=t.is_copy_mode;for _ in 0..5{t.note_control_state(true);assert_eq!(t.is_copy_mode,state);}states.push(state);t.note_control_state(false);}t.reset();rows.push(json!({"name":"control-toggle","press_states":states,"reset_clears":!t.is_copy_mode}));
std::fs::write(std::env::args().nth(1).unwrap(),serde_json::to_vec_pretty(&rows).unwrap()).unwrap();}
